-- Tubes & Flaps catalogue seed.
-- Generated from src/lib/tubes/data.json, the reviewed master dataset.
-- Apply after 20261105000000_tubes_flaps_catalogue.sql.
-- normalized_size is the loose lower-case alphanumeric search key.

begin;

on conflict (slug) do update set name = excluded.name, description = excluded.description, display_order = excluded.display_order, is_active = excluded.is_active;

on conflict (code) do update set aliases = excluded.aliases, source_texts = excluded.source_texts, image_path = excluded.image_path, display_order = excluded.display_order, is_active = excluded.is_active;

on conflict (application_slug, valve_code) do update set display_order = excluded.display_order;

on conflict (valve_code, application_slug, original_size, source_row) do update set normalized_size = excluded.normalized_size, source_valve_text = excluded.source_valve_text, source_table = excluded.source_table, verification_status = excluded.verification_status, display_order = excluded.display_order, is_active = excluded.is_active;

on conflict (original_size, source_row) do update set normalized_size = excluded.normalized_size, source_table = excluded.source_table, verification_status = excluded.verification_status, display_order = excluded.display_order, is_active = excluded.is_active;

commit;
